function genSteps(method: string) {
  const s: Record<string, { step: number; instruction: string }[]> = {
    "online": [
      { step: 1, instruction: "Log into your account on the website" },
      { step: 2, instruction: "Navigate to Account Settings or Subscription" },
      { step: 3, instruction: "Look for Cancel or Manage Subscription option" },
      { step: 4, instruction: "Follow the cancellation prompts and confirm" },
    ],
    "phone": [
      { step: 1, instruction: "Call customer service during business hours" },
      { step: 2, instruction: "Navigate the phone menu to reach cancellation department" },
      { step: 3, instruction: "Be prepared to decline retention offers" },
      { step: 4, instruction: "Request confirmation email or reference number" },
    ],
    "mail": [
      { step: 1, instruction: "Write a formal cancellation letter with your account details" },
      { step: 2, instruction: "Send via certified mail with return receipt" },
      { step: 3, instruction: "Keep copies of all correspondence" },
      { step: 4, instruction: "Follow up if no confirmation within 2 weeks" },
    ],
    "in-person": [
      { step: 1, instruction: "Visit your local branch or store" },
      { step: 2, instruction: "Bring ID and account information" },
      { step: 3, instruction: "Request to speak with a manager if needed" },
      { step: 4, instruction: "Get written confirmation of cancellation" },
    ],
    "store": [
      { step: 1, instruction: "Visit an authorized retail location" },
      { step: 2, instruction: "Bring your account details and ID" },
      { step: 3, instruction: "Request cancellation from a representative" },
      { step: 4, instruction: "Obtain written confirmation before leaving" },
    ],
  };
  return s[method] || s["online"];
}

async function main() {
  console.log("Seeding " + companies.length + " additional companies...");
  let seeded = 0;
  for (const co of companies) {
    const t = tpl[co.category] || tpl["Marketing Tools"];
    const method = t.methods[Math.floor(Math.random() * t.methods.length)];
    const patterns = t.patterns[Math.floor(Math.random() * t.patterns.length)];
    const diff = t.diff[0] + Math.random() * (t.diff[1] - t.diff[0]);
    const dark = t.dark[0] + Math.random() * (t.dark[1] - t.dark[0]);
    const data = {
      name: co.name, slug: co.slug, category: co.category, regions: co.regions,
      avgMonthlyPrice: co.price, yearlyPrice: co.price * 12 * 0.85,
      difficultyScore: Math.round(diff * 10) / 10,
      darkPatternScore: Math.round(dark * 10) / 10,
      clicksToCancel: method === "online" ? Math.floor(Math.random() * 5) + 3 : 0,
      estimatedCancelTime: method === "phone" ? Math.floor(Math.random() * 30) + 15 : Math.floor(Math.random() * 10) + 3,
      cancellationMethod: method,
      cancellationSteps: genSteps(method),
      freeTierAvailable: Math.random() > 0.7,
      headquarters: co.hq,
      darkPatterns: JSON.stringify(patterns),
      alternatives: JSON.stringify([]),
      totalCancellations: Math.floor(Math.random() * 50000) + 1000,
      verificationStatus: "verified",
      communityScore: Math.round(Math.random() * 50) / 10,
      successRate: Math.round((70 + Math.random() * 25) * 10) / 10,
    };
    try {
      await prisma.saasCompany.upsert({ where: { slug: co.slug }, update: data, create: data });
      seeded++;
    } catch { console.log("Skip: " + co.name); }
  }
  console.log("Done! Seeded " + seeded + " companies.");
}

main().catch((e) => { console.error(e); process.exit(1); }).finally(() => prisma.$disconnect());
